-- Isolated personal-chat feature storage. Existing chart chat tables are unchanged.
CREATE TABLE IF NOT EXISTS personal_chat_sessions(owner TEXT NOT NULL,id TEXT NOT NULL,profile_id TEXT NOT NULL,profile_revision INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'active',is_default INTEGER NOT NULL DEFAULT 1,created_at INTEGER NOT NULL,PRIMARY KEY(owner,id));
CREATE UNIQUE INDEX IF NOT EXISTS personal_chat_default_session ON personal_chat_sessions(owner,profile_id,profile_revision) WHERE is_default=1 AND status='active';
CREATE TABLE IF NOT EXISTS personal_chat_messages(owner TEXT NOT NULL,id TEXT NOT NULL,profile_id TEXT NOT NULL,profile_revision INTEGER NOT NULL,session_id TEXT NOT NULL,request_id TEXT NOT NULL,role TEXT NOT NULL,content TEXT NOT NULL,meta TEXT NOT NULL DEFAULT '{}',created_at INTEGER NOT NULL,PRIMARY KEY(owner,id),UNIQUE(owner,request_id,role));
CREATE INDEX IF NOT EXISTS personal_chat_message_scope ON personal_chat_messages(owner,profile_id,profile_revision,session_id,created_at);
CREATE TABLE IF NOT EXISTS personal_chat_runs(owner TEXT NOT NULL,id TEXT NOT NULL,profile_id TEXT NOT NULL,profile_revision INTEGER NOT NULL,session_id TEXT NOT NULL,fingerprint TEXT NOT NULL,status TEXT NOT NULL,lease_token TEXT NOT NULL,expires_at INTEGER NOT NULL,user_message_id TEXT NOT NULL,assistant_message_id TEXT,error_code TEXT,created_at INTEGER NOT NULL,PRIMARY KEY(owner,id));
CREATE UNIQUE INDEX IF NOT EXISTS personal_chat_active_run ON personal_chat_runs(owner,profile_id,profile_revision,session_id) WHERE status='running';
CREATE TABLE IF NOT EXISTS personal_chat_memories(owner TEXT NOT NULL,id TEXT NOT NULL,profile_id TEXT NOT NULL,profile_revision INTEGER NOT NULL,session_id TEXT NOT NULL,kind TEXT NOT NULL,content TEXT NOT NULL,source_id TEXT,source_quote TEXT NOT NULL,source_kind TEXT NOT NULL,domains TEXT NOT NULL,event_start TEXT,event_end TEXT,expires_at INTEGER,status TEXT NOT NULL DEFAULT 'active',supersedes_id TEXT,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,PRIMARY KEY(owner,id));
CREATE INDEX IF NOT EXISTS personal_chat_memory_scope ON personal_chat_memories(owner,profile_id,profile_revision,session_id,status);
CREATE TABLE IF NOT EXISTS personal_chat_summaries(owner TEXT NOT NULL,profile_id TEXT NOT NULL,profile_revision INTEGER NOT NULL,session_id TEXT NOT NULL,payload TEXT NOT NULL,updated_at INTEGER NOT NULL,PRIMARY KEY(owner,profile_id,profile_revision,session_id));
CREATE TABLE IF NOT EXISTS personal_chat_dismissed(owner TEXT NOT NULL,profile_id TEXT NOT NULL,profile_revision INTEGER NOT NULL,session_id TEXT NOT NULL,id TEXT NOT NULL,created_at INTEGER NOT NULL,PRIMARY KEY(owner,profile_id,profile_revision,session_id,id));
CREATE TABLE IF NOT EXISTS personal_chat_memory_events(owner TEXT NOT NULL,profile_id TEXT NOT NULL,profile_revision INTEGER NOT NULL,session_id TEXT NOT NULL,id TEXT NOT NULL,memory_id TEXT NOT NULL,payload TEXT NOT NULL,created_at INTEGER NOT NULL,PRIMARY KEY(owner,id));
CREATE INDEX IF NOT EXISTS personal_chat_memory_event_scope ON personal_chat_memory_events(owner,profile_id,profile_revision,session_id,created_at);
